<script setup lang="ts">
import { onMounted, ref } from 'vue';
type Media={id:number;url:string;original_name:string;mime_type:string;size:number;alt_text:string|null};
const items=ref<Media[]>([]), error=ref(''), busy=ref(false);
const csrf=()=>document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';
async function request(url:string,method='GET',body?:BodyInit,headers:Record<string,string>={}){const r=await fetch(url,{method,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf(),...headers},body});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Request failed');return d;}
async function load(){busy.value=true;try{const d=await request('/api/cms/media');items.value=d.data??[]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function upload(e:Event){const files=(e.target as HTMLInputElement).files;if(!files?.length)return;for(const file of Array.from(files)){const f=new FormData();f.append('file',file);try{await request('/api/cms/media-library','POST',f)}catch(x){error.value=(x as Error).message;break}}await load()}
async function edit(m:Media){const alt=window.prompt('Alternative text for accessibility',m.alt_text??'');if(alt===null)return;try{await request(`/api/cms/media/${m.id}`,'PATCH',JSON.stringify({alt_text:alt}),{'Content-Type':'application/json'});await load()}catch(e){error.value=(e as Error).message}}
async function remove(m:Media){if(!confirm(`Delete ${m.original_name}?`))return;try{await request(`/api/cms/media/${m.id}`,'DELETE');await load()}catch(e){error.value=(e as Error).message}}
onMounted(load);
</script>
<template><main class="wrap"><header><div><small>WEBSITE MANAGEMENT</small><h1>Media Library</h1><p>Upload and manage images used by CMS pages and banners.</p></div><label class="primary">＋ Upload images<input type="file" accept="image/*" multiple hidden @change="upload"></label></header><p v-if="error" class="error">{{error}}</p><p v-if="busy">Loading media…</p><section class="grid"><article v-for="m in items" :key="m.id"><img :src="m.url" :alt="m.alt_text||m.original_name"><div><strong>{{m.original_name}}</strong><small>{{(m.size/1024).toFixed(1)}} KB · {{m.mime_type}}</small><p>{{m.alt_text||'No alternative text'}}</p><button @click="edit(m)">Edit alt text</button><button class="danger" @click="remove(m)">Delete</button></div></article><p v-if="!busy&&!items.length" class="empty">No media uploaded yet.</p></section></main></template>
<style scoped>
.wrap{padding:24px;color:var(--text-primary,#172033)}header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}small{display:block;color:#64748b}h1{font-size:25px;margin:4px 0}p{color:#64748b}.primary,button{display:inline-block;padding:9px 13px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;cursor:pointer;text-decoration:none}.primary{background:#174c3c;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px}.grid article{border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;background:white}.grid img{width:100%;height:160px;object-fit:cover;background:#f1f5f9}.grid article>div{padding:12px}.grid strong{display:block;overflow-wrap:anywhere}.grid small{margin:5px 0}.grid button{margin:4px 5px 0 0}.danger{color:#b91c1c}.error{color:#b91c1c}.empty{padding:30px}@media(max-width:600px){header{align-items:flex-start;flex-direction:column}}
</style>
